def bind(library: Any, symbol: str) -> Any:
    """No loader, allocation, adoption, transfer or permission."""
    arguments, result = SIGNATURES[symbol]
    call = getattr(library, symbol)
    call.argtypes, call.restype = list(arguments), result
    return call
